/// Every ARB key of an app, as generated by
/// `dart run l10n_in_context:generate`.
///
/// The position of a key in [keys] is what edit-mode tags encode, so it is
/// only stable within one build.
class L10nCatalog {
  /// Creates a catalog. Normally only the generated code calls this.
  const L10nCatalog({required this.languages, required this.keys});

  /// The `@@locale` of every ARB file, e.g. `['en', 'hi']`.
  final List<String> languages;

  /// Every key, in template ARB order.
  final List<L10nKeyInfo> keys;

  static final Expando<Map<String, int>> _indexes = Expando();

  /// Position of [key] in [keys], or null for unknown keys.
  int? indexOf(String key) => (_indexes[this] ??= {
    for (var i = 0; i < keys.length; i++) keys[i].name: i,
  })[key];

  /// The key called [key], or null for unknown keys.
  L10nKeyInfo? lookup(String key) {
    final index = indexOf(key);
    return index == null ? null : keys[index];
  }
}

/// One ARB key as described by the template ARB.
class L10nKeyInfo {
  /// Creates a key. Normally only the generated code calls this.
  const L10nKeyInfo({
    required this.name,
    required this.description,
    required this.placeholders,
    required this.bundled,
    required this.overridable,
  });

  /// The ARB key, which is also the getter or method name.
  final String name;

  /// The `description` from the template ARB, or empty.
  final String description;

  /// Placeholders in declaration order.
  final List<L10nPlaceholder> placeholders;

  /// Raw ICU message per language, as written in the bundled ARB files.
  final Map<String, String> bundled;

  /// False for keys the app always takes from the bundled ARB (placeholders
  /// with a `format`, types the runtime formatter can't render), so editing
  /// them has no effect on screen.
  final bool overridable;

  /// Names of every placeholder.
  Set<String> get placeholderNames => {for (final p in placeholders) p.name};

  /// Arguments for previewing a message: each placeholder's ARB `example`,
  /// otherwise a value that fits its type.
  Map<String, Object> get exampleArgs => {
    for (final p in placeholders) p.name: p.exampleValue,
  };
}

/// One placeholder of an [L10nKeyInfo].
class L10nPlaceholder {
  /// Creates a placeholder. Normally only the generated code calls this.
  const L10nPlaceholder({required this.name, required this.type, this.example});

  /// The placeholder name, without braces.
  final String name;

  /// The Dart type gen-l10n uses, e.g. `String` or `int`.
  final String type;

  /// The ARB `example`, if any.
  final String? example;

  /// True for `int`, `num` and `double`.
  bool get isNumeric => const {'int', 'num', 'double'}.contains(type);

  /// [example] parsed for the type, or a default when there is none.
  Object get exampleValue {
    final example = this.example;
    if (isNumeric) return num.tryParse(example ?? '') ?? 3;
    return example ?? name;
  }
}
